/**
 * Wallet logos as data URIs (the CSP allows data: images, so nothing is fetched from wallet sites).
 * Taken from the official @solana/wallet-adapter-* packages (Apache-2.0, solana-labs/wallet-adapter):
 * phantom, solflare, backpack, coinbase, trust, bitkeep (Bitget), magiceden, exodus.
 * OKX has no adapter package; its five-square mark is drawn here as a plain SVG.
 * Generated file: re-run the extraction instead of editing by hand.
 */
export const WALLET_ICONS = {
  phantom: "data:image/svg+xml;base64,",
  solflare: "data:image/svg+xml;base64,",
  backpack: "data:image/png;base64,",
  okx: "data:image/svg+xml;base64,",
  coinbase: "data:image/svg+xml;base64,",
  trust: "data:image/svg+xml;base64,",
  bitkeep: "data:image/svg+xml;base64,",
  magiceden: "data:image/svg+xml;base64,",
  exodus: "data:image/svg+xml;base64,",
} as const;

export type WalletIconKey = keyof typeof WALLET_ICONS;
